            <div class="card-header">
                <strong>Tracking #:</strong> <code>@s.TrackingNumber</code>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Status</dt>
                            <dd><span class="badge @GetStatusBadge(s.Status) fs-6">@s.Status</span></dd>
                            <dt>Origin</dt>
                            <dd>@s.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@s.Destination</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Estimated Delivery</dt>
                            <dd class="fs-5">
                                @if (s.EstimatedDelivery.HasValue)
                                {
                                    <strong>@s.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</strong>
                                }
                                else
                                {
                                    <span class="text-muted">Not yet determined</span>
                                }
                            </dd>
                            <dt>Description</dt>
                            <dd>@(string.IsNullOrEmpty(s.Description) ? "—" : s.Description)</dd>
                            <dt>Shipped On</dt>
                            <dd>@s.CreatedAt.ToString("MMMM dd, yyyy")</dd>
                        </dl>
                    </div>
                </div>

                <h5 class="mt-3">Delivery Progress</h5>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressColor(s.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(s.Status))%"
                         aria-valuenow="@GetProgressPercent(s.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @s.Status
                    </div>
                </div>
            </div>
        </div>
    }
}

