using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    public DateTime? EstimatedDelivery { get; set; }

    [MaxLength(256)]
    public string CustomerEmail { get; set; } = string.Empty;

    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<TrackingResult> TrackShipmentAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

        if (shipment is null)
            return new TrackingResult { Found = false };

        return new TrackingResult { Found = true, Shipment = ToDto(shipment) };
    }

    public async Task UpdateStatusAsync(UpdateShipmentStatusRequest request)
    {
        var shipment = await db.Shipments.FindAsync(request.ShipmentId);
        if (shipment is not null)
        {
            shipment.Status = (int)request.NewStatus;
            await db.SaveChangesAsync();
        }
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = dto.Origin,
            Destination = dto.Destination,
            CustomerEmail = dto.CustomerEmail,
            Description = dto.Description,
            Status = (int)ShipmentStatus.Pending,
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = DateTime.UtcNow.AddDays(Random.Shared.Next(3, 14))
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();

        return ToDto(shipment);
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000, 9999)}";
    }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
        {
            return Results.Ok(await service.GetAllShipmentsAsync());
        });

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            return Results.Ok(await service.TrackShipmentAsync(trackingNumber));
        }).AllowAnonymous();

        group.MapPut("status", async (UpdateShipmentStatusRequest request, IShipmentService service) =>
        {
            await service.UpdateStatusAsync(request);
            return Results.Ok();
        });

        group.MapPost("", async (ShipmentDto dto, IShipmentService service) =>
        {
            var result = await service.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/{result.Id}", result);
        });
    }
}

